import "server-only";

/**
 * Fonts for share cards (Satori needs TTF, not WOFF2): Geist Pixel Square and
 * Geist Regular, subset to Latin + punctuation. Generated from the geist
 * package (SIL Open Font License). Don't edit by hand.
 */
const b64 = (s: string) => Buffer.from(s, "base64");

export const ogFonts = () => [
  { name: "Geist Pixel", data: b64(PIXEL), weight: 400 as const, style: "normal" as const },
  { name: "Geist", data: b64(SANS), weight: 400 as const, style: "normal" as const },
];

const PIXEL = "";
const SANS = "";
